@startuml

abstract class Property {
  + code : string
  + address : string
  + zipCode : string
  + city : string
  + area : int
  + getPropertyDetails() : string
  + search(key : string) : void
}

class Garage extends Property {
  + numberOfParkingSpaces : int
}

class Apartment extends Property {
  + numberOfRooms : int
  + numberOfBathrooms : int
}

class Villa extends Apartment {
  + gardenSize : int
}

@enduml

